public class GridMutationProbe {
 public static String observe() {
  Object[][][] grid = new Object[][][]{};
  grid.add(new Object[][]{});
  grid[0].add(new Object[]{});
  grid[0][0].add(null);
  Integer before = grid[0][0].size();
  grid[0][0][0] = 'sample';
  grid[0].add(new Object[]{});
  grid[0][1].add('sibling');
  grid[0].add(new Object[]{});
  Object[] alias = grid[0][0];
  alias.add('alias');
  List<List<List<Integer>>> genericGrid = new List<List<List<Integer>>>{new List<List<Integer>>{new List<Integer>()}};
  genericGrid[0][0].add(9);
  Object[][] flat = new Object[][]{new Object[]{}};
  flat[0].add('flat');
  String invalid = '';
  try { grid[0][3].add('bad'); } catch (ListException e) { invalid = e.getTypeName(); }
  return 'rows:' + before + ':' + grid[0][0].size() + ':' + grid[0][0][0] + ':' + grid[0][0][1]
   + '|sibling:' + grid[0][1].size() + ':' + grid[0][1][0]
   + '|untouched:' + grid[0][2].size()
   + '|generic:' + genericGrid[0][0].size() + ':' + genericGrid[0][0][0]
   + '|flat:' + flat[0].size() + ':' + flat[0][0] + '|bounds:' + invalid;
 }
}

